 public void Initialize(Transform surface,Camera camera){transform.SetParent(surface,false);var parent=surface.GetComponent<RectTransform>();var r=gameObject.GetComponent<RectTransform>();if(r==null)r=gameObject.AddComponent<RectTransform>();r.anchorMin=r.anchorMax=Vector2.one*.5f;r.sizeDelta=new Vector2(1280,800);root=r;var canvas=surface.GetComponentInParent<Canvas>();if(canvas!=null){canvas.worldCamera=camera;if(canvas.GetComponent<GraphicRaycaster>()==null)canvas.gameObject.AddComponent<GraphicRaycaster>();}Build();Resize();}
 void Build(){root.gameObject.AddComponent<Image>().color=new Color(.025f,.04f,.065f);fade=gameObject.AddComponent<CanvasGroup>();heading=GridShiftUI.Text(root,"URBAN FLOW — CENTRAL DE OPERAÇÕES",27,50);heading.rectTransform.anchorMin=heading.rectTransform.anchorMax=new Vector2(0,1);heading.rectTransform.pivot=new Vector2(0,1);heading.rectTransform.anchoredPosition=new Vector2(24,-15);heading.rectTransform.sizeDelta=new Vector2(1200,50);heading.color=new Color(1,.83f,.2f);
 var nav=GridShiftUI.Rect("Abas",root,new Vector2(265,780));nav.anchorMin=nav.anchorMax=new Vector2(0,1);nav.pivot=new Vector2(0,1);nav.anchoredPosition=new Vector2(12,-110);GridShiftUI.Stack(nav,8,10);foreach(var label in new[]{"Visão Geral","Entregas","Frota","Financeiro","Funcionários","Missões","Upgrades","Mapa","Configurações"}){string target=label;var tab=GridShiftUI.Button(nav,label,()=>Show(target),64);tabs[label]=tab;var caption=tab.GetComponentInChildren<TMP_Text>();caption.fontSize=26;caption.enableAutoSizing=true;caption.fontSizeMin=23;caption.fontSizeMax=26;caption.rectTransform.offsetMin=new Vector2(40,2);caption.rectTransform.offsetMax=new Vector2(-8,-2);}content=GridShiftUI.Scroll(root,new Vector2(285,70),new Vector2(-18,-110),out scroll);contentFade=content.gameObject.AddComponent<CanvasGroup>();indicators=GridShiftUI.Text(root,"",24,40);indicators.rectTransform.anchorMin=indicators.rectTransform.anchorMax=new Vector2(0,1);indicators.rectTransform.pivot=new Vector2(0,1);indicators.rectTransform.anchoredPosition=new Vector2(26,-65);indicators.rectTransform.sizeDelta=new Vector2(1210,40);feedback=GridShiftUI.Text(root,"",21,45);feedback.rectTransform.anchorMin=feedback.rectTransform.anchorMax=new Vector2(0,0);feedback.rectTransform.pivot=new Vector2(0,0);feedback.rectTransform.anchoredPosition=new Vector2(260,12);feedback.rectTransform.sizeDelta=new Vector2(980,50);feedback.color=new Color(1,.85f,.3f);}
 void Resize(){if(root==null||transform.parent==null)return;var area=((RectTransform)transform.parent).rect.size;if(area.x<=0||area.y<=0)return;float width=Mathf.Max(1280,900*area.x/area.y);root.sizeDelta=new Vector2(width,width*area.y/area.x);root.localScale=Vector3.one*(area.x/width*.95f);root.anchoredPosition=Vector2.zero;}
