 public void Open(){Active=this;manager=DeliveryManager.Instance;if(manager==null)return;manager.OperationsViewed=true;manager.StateChanged-=Dirty;manager.StateChanged+=Dirty;gameObject.SetActive(true);Show(page);StartCoroutine(Appear());}
