 public void Show(string tab){page=tab;form=false;shown=-1;scroll.StopMovement();scroll.verticalNormalizedPosition=1;if(manager!=null&&tab=="Entregas")manager.Company.Missions.VisitOperations();Render();foreach(var entry in tabs)GridShiftUITheme.Button(entry.Value,entry.Key==tab);if(tabTransition!=null)StopCoroutine(tabTransition);tabTransition=StartCoroutine(TabFade());}
