 void Clear(){ReleaseMap();foreach(Transform child in content){child.gameObject.SetActive(false);Destroy(child.gameObject);}scroll.verticalNormalizedPosition=1;}
 void Message(bool ok,string text){feedback.text=text??(ok?"Operação concluída.":"Operação indisponível.");Dirty();}
