 void Render(){if(manager==null||!manager.Company.Ready)return;float position=scroll.verticalNormalizedPosition;Clear();shown=manager.Version;var company=manager.Company;var state=company.State;GridShiftUI.Text(content,page=="Funcionários"?"Funcionários ("+company.Employees+")":page,34,52);
 switch(page){case "Visão Geral":var overview=GridShiftUI.Card(content,GridShiftProfiles.CompanyName,290);GridShiftUI.Text(overview,"Saldo: R$ "+manager.Money.ToString("N2")+"  ·  Reputação: "+state.reputation+"/100",25,44);GridShiftUI.Text(overview,"Ato "+state.act+"  ·  Dia "+((int)company.Day+1)+"  ·  Funcionários: "+company.Employees+"  ·  Frota: "+manager.fleet.Count,23,42);GridShiftUI.Text(overview,state.news,23,88);GridShiftUI.Button(overview,"Salvar progresso",()=>{bool ok=manager.GetComponent<DeliveryPersistence>().Save();Message(ok,ok?"Progresso salvo no slot ativo.":"Escolha um perfil e um slot pelo menu de pausa.");});break;
 case "Entregas":Deliveries();break;case "Financeiro":Finance();break;case "Funcionários":foreach(var e in state.employees){var employee=e;var card=GridShiftUI.Card(content,e.name+" — "+e.role,230);GridShiftUI.Text(card,"Salário semanal: R$ "+e.salary.ToString("N2")+" · Experiência "+e.experience,23,35);GridShiftUI.Text(card,e.benefit,22,50);GridShiftUI.Button(card,e.hired?"Desligar":"Contratar",()=>Act(employee.hired?"dismiss":"hire",employee.id));}break;
 case "Frota":foreach(var v in manager.fleet.Where(v=>v!=null)){var vehicle=v;var h=company.Health(v.id);var card=GridShiftUI.Card(content,v.id+" · "+v.kind+" · "+v.capacityKg.ToString("0")+" kg",350);GridShiftUI.Text(card,"Combustível: "+h.fuel.ToString("0.0")+"% · Condição: "+h.condition.ToString("0.0")+"%",24,40);GridShiftUI.Text(card,h.maintenanceUntil>company.Day?"Em manutenção":"Estado: "+v.state,23,35);GridShiftUI.Button(card,manager.TrackedVehicleId==v.id?"Parar acompanhamento":"Acompanhar veículo",()=>{if(manager.TrackedVehicleId==vehicle.id)manager.StopTracking();else manager.TrackVehicle(vehicle.id);});GridShiftUI.Button(card,"Abastecer",()=>Act("refuel",vehicle.id));GridShiftUI.Button(card,"Solicitar manutenção",()=>Act("repair",vehicle.id));}break;
 case "Missões":foreach(var m in state.missions){var mission=m;var card=GridShiftUI.Card(content,m.name,390);GridShiftUI.Text(card,company.Missions.StateLabel(m),25,80);GridShiftUI.Text(card,m.description,22,70);GridShiftUI.Text(card,company.Missions.ProgressText(m),25,175);if(m.status==CompanyMissionStatus.Locked){GridShiftUI.Text(card,m.requirement,22,65);continue;}if(!m.rewardClaimed)GridShiftUI.Button(card,state.selectedMission==m.id?"Parar acompanhamento":"Acompanhar missão",()=>{if(state.selectedMission==mission.id){state.selectedMission=null;company.NotifyChanged();company.Save();}else Act("select-mission",mission.id);});if(m.id=="first-contract"&&m.step==1)GridShiftUI.Button(card,"Ler oportunidade de Carlos",()=>Act("read-mission",mission.id));else if(m.id=="first-contract"&&m.step==6)GridShiftUI.Button(card,"Abrir operações",()=>Show("Entregas"));else if((m.id=="first-contract"&&m.step>=7&&m.step<=8)||(m.id=="city-top"&&m.status==CompanyMissionStatus.Available)||(m.id=="neighborhood"&&m.status==CompanyMissionStatus.Available)){foreach(var v in manager.fleet.Where(v=>v!=null&&v.Available&&v.kind==(m.id=="city-top"?FleetKind.Truck:FleetKind.Car))){string id=v.id;GridShiftUI.Button(card,"Selecionar "+id+" e iniciar",()=>Act(mission.id=="neighborhood"?"start-side":"start-mission",id));}}else if(!m.rewardClaimed&&company.Missions.RequirementsMet(m))GridShiftUI.Button(card,"Confirmar conclusão e receber bônus",()=>Act("confirm-mission",mission.id));}break;
 case "Upgrades":foreach(var u in manager.Progression.Catalog()){var upgrade=u;var card=GridShiftUI.Card(content,u.name+" · "+u.level+"/"+u.maxLevel,245);GridShiftUI.Text(card,u.description,22,65);GridShiftUI.Text(card,u.requirement,20,30);var b=GridShiftUI.Button(card,"Comprar · R$ "+u.cost.ToString("N2"),()=>{bool ok=manager.Progression.Buy(upgrade.id,out var error);Message(ok,error);});b.interactable=u.canBuy;}break;
