 void Deliveries(){GridShiftUI.Button(content,"Criar entrega",CreateForm,52,true);GridShiftUI.Text(content,"CONTRATOS DISPONÍVEIS",25,45);foreach(var o in manager.Offers()){var offer=o;var card=GridShiftUI.Card(content,o.goods+" · "+o.weightKg+" kg",195);GridShiftUI.Text(card,manager.Point(o.pickupId)?.displayName+" → "+manager.Point(o.destinationId)?.displayName,22,60);GridShiftUI.Button(card,"Aceitar contrato",()=>{bool ok=manager.Accept(offer.id,out var error);Message(ok,error);});}GridShiftUI.Text(content,"ENTREGAS ATIVAS E HISTÓRICO",25,45);foreach(var o in manager.orders.AsEnumerable().Reverse()){var order=o;var card=GridShiftUI.Card(content,o.goods+" · "+DeliveryPresentation.StatusName(o.status),235);GridShiftUI.Text(card,(o.vehicleId??"Aguardando veículo")+" · "+o.weightKg+" kg · R$ "+o.reward.ToString("N2"),23,40);GridShiftUI.Text(card,manager.Point(o.destinationId)?.displayName,23,40);GridShiftUI.Button(card,manager.SelectedId==o.id?"Parar acompanhamento":"Acompanhar entrega",()=>{if(manager.SelectedId==order.id)manager.StopTracking();else manager.Select(order.id);});}}
 void Finance(){var company=manager.Company;GridShiftUI.Text(content,"CONTAS A PAGAR · dia "+((int)company.Day+1),25,45);foreach(var b in company.State.bills.OrderBy(x=>x.paid)){var bill=b;var card=GridShiftUI.Card(content,b.description,b.paid?165:285);GridShiftUI.Text(card,"R$ "+(b.amount+b.lateFee).ToString("N2")+" · Vence no dia "+((int)b.dueDay+1),23,40);GridShiftUI.Text(card,b.paid?"Paga":company.Day>b.dueDay?"Vencida · multa única":"Pendente",23,35);if(!b.paid){GridShiftUI.Button(card,"Pagar conta",()=>Act("pay-bill",bill.id));if(!b.deferred)GridShiftUI.Button(card,"Renegociar +3 dias",()=>Act("defer-bill",bill.id));}}GridShiftUI.Button(content,"Apoio de retomada",()=>Act("recovery",null));GridShiftUI.Text(content,"FECHAMENTOS SEMANAIS · valores fictícios de gameplay",24,50);foreach(var w in company.State.weeks.AsEnumerable().Reverse()){var card=GridShiftUI.Card(content,"Semana "+w.week,220);GridShiftUI.Text(card,"Receitas R$ "+w.revenue.ToString("N2")+" · Despesas pagas R$ "+w.expenses.ToString("N2"),23,45);GridShiftUI.Text(card,"Resultado de caixa R$ "+w.profit.ToString("N2")+" · Contas emitidas R$ "+w.invoiced.ToString("N2"),23,55);GridShiftUI.Text(card,"Saldo no fechamento: R$ "+w.balance.ToString("N2"),23,40);}GridShiftUI.Text(content,"HISTÓRICO FINANCEIRO",24,45);foreach(var t in company.State.ledger.AsEnumerable().Reverse().Take(100))GridShiftUI.Text(content,t.category+" · "+t.description+" · R$ "+t.amount.ToString("N2"),21,65);}
 void CreateForm(){Clear();form=true;GridShiftUI.Text(content,"NOVA ENTREGA",30,45);cargo=GridShiftUI.Input(content,"Mercadoria");weight=GridShiftUI.Input(content,"Peso (kg)");weight.text="5";var pts=manager.points.Where(p=>p!=null&&p.Valid&&manager.Progression.Unlocked(p)).ToArray();pickupIndex=0;destinationIndex=pts.Length>1?1:0;Button a=null,b=null;a=GridShiftUI.Button(content,"Origem: "+(pts.Length>0?pts[0].displayName:"Sem locais"),()=>{pickupIndex=(pickupIndex+1)%Mathf.Max(1,pts.Length);a.GetComponentInChildren<TMP_Text>().text="Origem: "+pts[pickupIndex].displayName;});b=GridShiftUI.Button(content,"Destino: "+(pts.Length>0?pts[destinationIndex].displayName:"Sem locais"),()=>{destinationIndex=(destinationIndex+1)%Mathf.Max(1,pts.Length);b.GetComponentInChildren<TMP_Text>().text="Destino: "+pts[destinationIndex].displayName;});GridShiftUI.Button(content,"Confirmar entrega",()=>{if(pts.Length<2||!float.TryParse(weight.text.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out var kg)){Message(false,"Informe locais válidos e peso numérico.");return;}bool ok=manager.TryCreate(new DeliveryRequest{goods=cargo.text,weightKg=kg,pickupId=pts[pickupIndex].id,destinationId=pts[destinationIndex].id},out _,out var error);Message(ok,error);if(ok){manager.GetComponent<DeliveryPersistence>().RequestSave();Show("Entregas");}},52,true);GridShiftUI.Button(content,"Voltar",()=>Show("Entregas"));}
 void ReleaseMap(){if(mapCamera!=null){mapCamera.enabled=false;mapCamera.targetTexture=null;Destroy(mapCamera.gameObject);}if(mapTexture!=null){mapTexture.Release();Destroy(mapTexture);}mapCamera=null;mapTexture=null;}
 void Map(){var city=UnityEngine.Object.FindObjectsByType<PlayerMovement>(FindObjectsInactive.Include,FindObjectsSortMode.None).FirstOrDefault(p=>p.gameObject.scene.name=="SampleScene");var source=city!=null?city.GetComponentInChildren<MinimapCamera>(true)?.GetComponent<Camera>():null;if(source==null){GridShiftUI.Text(content,"Mapa indisponível nesta cena.");return;}mapCamera=new GameObject("NativeOperationsMapCamera").AddComponent<Camera>();mapCamera.CopyFrom(source);mapCamera.transform.SetPositionAndRotation(source.transform.position,source.transform.rotation);mapCamera.orthographicSize=150;mapTexture=new RenderTexture(800,400,16);mapTexture.Create();mapCamera.targetTexture=mapTexture;mapCamera.enabled=true;var r=GridShiftUI.Rect("Mapa nativo",content,new Vector2(900,450));var image=r.gameObject.AddComponent<RawImage>();image.texture=mapTexture;var markers=r.gameObject.AddComponent<GridShiftMapMarkers>();markers.image=image;markers.mapCamera=mapCamera;markers.manager=manager;markers.player=city.transform;markers.expanded=true;var drag=r.gameObject.AddComponent<GridShiftNativeMapDrag>();drag.cameraView=mapCamera;GridShiftUI.Button(content,"Centralizar no veículo",()=>MapCenter(manager.TrackedVehicle!=null?manager.TrackedVehicle.transform.position:city.transform.position));GridShiftUI.Button(content,"Ver destino",()=>{var p=manager.Selected!=null?manager.Point(manager.Selected.destinationId):null;if(p!=null)MapCenter(p.Stop);});GridShiftUI.Button(content,"Voltar ao jogador",()=>MapCenter(city.transform.position));GridShiftUI.Button(content,"Zoom +",()=>mapCamera.orthographicSize=Mathf.Clamp(mapCamera.orthographicSize*.8f,15,400));GridShiftUI.Button(content,"Zoom −",()=>mapCamera.orthographicSize=Mathf.Clamp(mapCamera.orthographicSize*1.25f,15,400));GridShiftUI.Button(content,"Parar acompanhamento",manager.StopTracking);}void MapCenter(Vector3 at){if(mapCamera!=null){var pos=mapCamera.transform.position;pos.x=at.x;pos.z=at.z;mapCamera.transform.position=pos;}}
 void RouteSettings(){var settings=manager.GetComponent<GridShiftRouteView>();if(settings==null)return;GridShiftUI.Text(content,"Visualização da rota acompanhada",27,48);GridShiftUI.Button(content,settings.showInWorld?"Rota: mapa e mundo 3D":"Rota: somente mapa e minimapa",()=>{settings.showInWorld=!settings.showInWorld;settings.SavePreferences();Dirty();});GridShiftUI.Button(content,"Espessura: "+settings.mapWidth.ToString("0.0")+" px / "+settings.worldWidth.ToString("0.00")+" m",()=>{settings.mapWidth=settings.mapWidth>=5?1.8f:settings.mapWidth+.8f;settings.worldWidth=Mathf.Clamp(settings.mapWidth*.03f,.04f,.15f);settings.SavePreferences();Dirty();});GridShiftUI.Button(content,"Transparência: "+Mathf.RoundToInt((1-settings.transparency)*100)+"%",()=>{settings.transparency=settings.transparency>=.9f?.4f:settings.transparency+.15f;settings.SavePreferences();Dirty();});GridShiftUI.Button(content,"Cor: azul / ciano",()=>{settings.routeColor=settings.routeColor.g>.7f?new Color(.2f,.6f,1):new Color(.3f,.85f,1);settings.SavePreferences();Dirty();});GridShiftUI.Button(content,"Distância no mundo: "+settings.viewDistance+" m",()=>{settings.viewDistance=settings.viewDistance>=100?30:settings.viewDistance+20;settings.SavePreferences();Dirty();});}
 void Volume(){var r=GridShiftUI.Rect("Volume",content,new Vector2(700,40));var slider=r.gameObject.AddComponent<Slider>();GridShiftUITheme.Surface(r.gameObject.AddComponent<Image>(),"Slider_Trilho_Vazio");r.GetComponent<Image>().raycastTarget=true;var fill=GridShiftUI.Rect("Fill",r,Vector2.zero);GridShiftUI.Stretch(fill,Vector2.zero,Vector2.zero);GridShiftUITheme.Surface(fill.gameObject.AddComponent<Image>(),"Slider_Preenchimento_Amarelo");var handle=GridShiftUI.Rect("Handle",r,new Vector2(30,46));GridShiftUITheme.Surface(handle.gameObject.AddComponent<Image>(),"Slider_Puxador",false);slider.fillRect=fill;slider.handleRect=handle;slider.targetGraphic=handle.GetComponent<Image>();slider.SetValueWithoutNotify(AudioListener.volume);slider.onValueChanged.AddListener(v=>{AudioListener.volume=v;PlayerPrefs.SetFloat("GS.Volume",v);});}
